$jwt = $env:SUPABASE_JWT; if(-not $jwt){ $payload = @{id='t';perfil='admin'} | ConvertTo-Json; $secret = 'italy_secret_2026'; $head64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes((@{alg='HS256';typ='JWT'}|ConvertTo-Json -Compress))).TrimEnd('=').Replace('+','-').Replace('/','_'); $pl64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($payload)).TrimEnd('=').Replace('+','-').Replace('/','_'); $hmac = New-Object System.Security.Cryptography.HMACSHA256; $hmac.Key = [Text.Encoding]::UTF8.GetBytes($secret); $sig = [Convert]::ToBase64String($hmac.ComputeHash([Text.Encoding]::UTF8.GetBytes("$head64.$pl64"))).TrimEnd('=').Replace('+','-').Replace('/','_'); $jwt = "$head64.$pl64.$sig"; }
$headers = @{Authorization="Bearer $jwt";Accept='application/json';'Cache-Control'='no-cache'}
Write-Output '=== CLIENTES ==='; try { $r = Invoke-RestMethod -Uri 'https://adm.italyembalagens.com.br/api/clientes?limit=900' -Headers $headers -Method Get -UseBasicParsing -TimeoutSec 60 } catch { $r = $_.Exception.Message }; if($r){ $arr = @(); if($r.data -is [array]){$arr=$r.data}elseif($r -is [array]){$arr=$r}; $norm = {param($s) if(-not $s){return ''}; $t = $s.Normalize([Text.NormalizationForm]::FormD); $sb = New-Object Text.StringBuilder; foreach($c in $t.ToCharArray()){ if([Globalization.CharUnicodeInfo]::GetUnicodeCategory($c) -ne [Globalization.UnicodeCategory]::NonSpacingMark){ [void]$sb.Append($c) } }; return $sb.ToString().ToLower().Trim() -replace '\s+',' ' }; $m = @(); foreach($o in $arr){ $n = & $norm ($o.nome + ' ' + $o.razao_social + ' ' + $o.nome_fantasia); if($n -match 'ripke'){ $m += [pscustomobject]@{id=$o.id.ToString().Substring(0,[Math]::Min(14,$o.id.ToString().Length));nome=$o.nome;empresa_id=($o.empresa_id??$o.emp_id??$null);deleted=[bool]$o.deleted_at;status=$o.status} } }; $m | ConvertTo-Json -Depth 3 } else { Write-Output "no data: $r" }